// Escenas a medida de largo-20-01: «What If the Moon Disappeared? 5 Myths vs Reality»
// Horizontal: se ve x ≈ -860…1940 e y ≈ 230…1810 (lo importante en y 350-1350).

const SZ = 1.45;
function bg(ctx, K, c1, c2) { const g = ctx.createLinearGradient(0, 0, 0, 1920); g.addColorStop(0, c1); g.addColorStop(1, c2); ctx.fillStyle = g; ctx.fillRect(K.X0, 0, K.XW, 1920); }
function floor(ctx, K, y, col) { ctx.fillStyle = col; ctx.fillRect(K.X0, y, K.XW, 1920 - y); ctx.fillStyle = K.INK; ctx.fillRect(K.X0, y - 4, K.XW, 8); }
function veil(ctx, K, col, al) { if (al <= 0) return; ctx.globalAlpha = Math.min(1, al); ctx.fillStyle = col; ctx.fillRect(K.X0, 0, K.XW, 1920); ctx.globalAlpha = 1; }
function stand(ctx, a, K, x, fy, s, w, mood = 'neutral', o = {}) { s *= SZ; const y = fy - 2290 * s + Math.sin(a.t * 2.2 + x * 0.01) * 4; K.drawFullBody(ctx, x, y, s, w, { mood, t: a.t, ...o }); return y - 330 * s; }
const you = (a, o = {}) => ({ ...a.who, ...o });
function stars(ctx, K, t, n = 160, al = 1) { for (let i = 0; i < n; i++) { const tw = 0.6 + 0.4 * Math.sin(t * 2 + i); ctx.globalAlpha = al * tw; K.C(ctx, K.X0 + (i * 397) % K.XW, 230 + (i * 233) % 1100, 2 + (i % 3) * 1.5, '#ffffff', 0); } ctx.globalAlpha = 1; }
function night(ctx, K, t, n = 160) { bg(ctx, K, '#070a1f', '#1d2350'); stars(ctx, K, t, n); }
function moon(ctx, K, x, y, r, k = 1, glow = true) { if (k <= 0) return; ctx.save(); ctx.globalAlpha = k; if (glow) K.radial(ctx, x, y, r * 2.6, '#fff6d8', 0.5); const g = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, r * 0.1, x, y, r); g.addColorStop(0, '#f4f2ea'); g.addColorStop(1, '#bdb9ad'); ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fillStyle = g; ctx.fill(); ctx.save(); ctx.clip(); for (let i = 0; i < 9; i++) K.C(ctx, x + Math.cos(i * 2.3) * r * 0.55, y + Math.sin(i * 1.7) * r * 0.55, r * (0.08 + (i % 3) * 0.05), 'rgba(120,115,105,0.35)', 0); ctx.restore(); ctx.lineWidth = Math.max(5, r * 0.04); ctx.strokeStyle = K.INK; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.stroke(); ctx.restore(); }
function sun(ctx, K, x, y, r) { K.radial(ctx, x, y, r * 2.4, '#ffd166', 0.55); K.C(ctx, x, y, r, '#ffd23f', Math.max(6, r * 0.05)); }
function earth(ctx, K, x, y, r, t, tilt = 0) { ctx.save(); ctx.translate(x, y); ctx.rotate(tilt); K.C(ctx, 0, 0, r, '#3a8fd6', Math.max(6, r * 0.04)); ctx.save(); ctx.beginPath(); ctx.arc(0, 0, r, 0, 7); ctx.clip(); const o = (t * 0.15 % 2) * r; for (const [cx, cy, rx, ry] of [[-0.3, -0.25, 0.45, 0.3], [0.4, 0.3, 0.3, 0.4], [-0.5, 0.45, 0.25, 0.18], [0.2, -0.6, 0.3, 0.15]]) for (const sh of [-2, 0]) K.E(ctx, (cx + sh) * r + o, cy * r, rx * r, ry * r, '#5fb35a', 0.3, 0); K.E(ctx, 0, -r * 0.92, r * 0.6, r * 0.14, '#ffffff', 0, 0); K.E(ctx, 0, r * 0.92, r * 0.6, r * 0.14, '#ffffff', 0, 0); ctx.restore(); ctx.restore(); }
function beach(ctx, K, t, dark = 0) {
  bg(ctx, K, '#070a1f', '#24305f'); stars(ctx, K, t, 120);
  ctx.fillStyle = '#1d3a6a'; ctx.fillRect(K.X0, 1000, K.XW, 400); for (let i = 0; i < 8; i++) { ctx.strokeStyle = 'rgba(191,233,255,0.5)'; ctx.lineWidth = 6; ctx.beginPath(); for (let x = K.X0; x <= K.X0 + K.XW; x += 60) { const y = 1040 + i * 45 + Math.sin(x / 120 + t * 2 + i) * 8; x === K.X0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y); } ctx.stroke(); }
  floor(ctx, K, 1380, '#c9b37a'); if (dark) veil(ctx, K, '#000008', dark);
}
function ocean(ctx, K, t, level = 0, col = '#3a8fd6') { ctx.fillStyle = col; ctx.beginPath(); const y0 = 1100 - level; ctx.moveTo(K.X0, y0); for (let x = K.X0; x <= K.X0 + K.XW; x += 60) ctx.lineTo(x, y0 + Math.sin(x / 140 + t * 2.4) * 14); ctx.lineTo(K.X0 + K.XW, 1920); ctx.lineTo(K.X0, 1920); ctx.fill(); ctx.lineWidth = 8; ctx.strokeStyle = K.INK; ctx.stroke(); }
function myth(ctx, K, a, n, txt) { const k = K.ph(a.t, a.d, 0, 0.25); ctx.save(); ctx.translate(540, 650); ctx.rotate(-0.04); ctx.scale(K.ease.outBack(k), K.ease.outBack(k)); K.R(ctx, -620, -240, 1240, 480, 40, '#ffd166', 12); K.text(ctx, `MYTH #${n}`, 0, -120, { size: 110, color: '#7a2333' }); K.text(ctx, txt, 0, 60, { size: 72, color: '#2b3a66' }); ctx.restore(); }
function busted(ctx, K, x, y, k, label = 'BUSTED') { if (k <= 0) return; ctx.save(); ctx.translate(x, y); ctx.rotate(-0.18); ctx.scale(K.ease.outBack(k) * 1.1, K.ease.outBack(k) * 1.1); ctx.lineWidth = 18; ctx.strokeStyle = '#ff3b30'; ctx.strokeRect(-330, -95, 660, 190); K.text(ctx, label, 0, 0, { size: 120, color: '#ff3b30' }); ctx.restore(); }
function reality(ctx, K, x, y, k) { if (k <= 0) return; ctx.save(); ctx.translate(x, y); ctx.scale(K.ease.outBack(k), K.ease.outBack(k)); K.R(ctx, -260, -70, 520, 140, 30, '#2ec27e', 9); K.text(ctx, 'REALITY', 0, 0, { size: 80, color: '#ffffff' }); ctx.restore(); }
function bubbles(ctx, K, x, y, t, n = 8, col = 'rgba(255,255,255,0.7)') { for (let i = 0; i < n; i++) { const q = (t * 0.6 + i / n) % 1; K.C(ctx, x + Math.sin(i * 2 + t) * 60, y - q * 500, 8 + (i % 3) * 5, col, 3); } }
function reef(ctx, K, t) { bg(ctx, K, '#0e4a7a', '#06223f'); for (let i = 0; i < 6; i++) { ctx.fillStyle = 'rgba(160,220,255,0.08)'; ctx.beginPath(); ctx.moveTo(-600 + i * 500, 200); ctx.lineTo(-450 + i * 500, 200); ctx.lineTo(-300 + i * 500 + Math.sin(t) * 40, 1400); ctx.lineTo(-700 + i * 500, 1400); ctx.fill(); }
  floor(ctx, K, 1300, '#d9c49a'); for (let i = 0; i < 16; i++) { const x = K.X0 + 400 + i * 200, c = ['#ff7a9a', '#ffb347', '#b67bff', '#ff5c5c', '#ffd166'][i % 5]; if (i % 3 === 0) { for (let b = -2; b <= 2; b++) { ctx.strokeStyle = c; ctx.lineWidth = 22; ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(x, 1300); ctx.quadraticCurveTo(x + b * 30, 1180, x + b * 50 + Math.sin(t + i + b) * 6, 1100 - Math.abs(b) * 20); ctx.stroke(); } } else if (i % 3 === 1) { ctx.fillStyle = c; ctx.beginPath(); ctx.arc(x, 1300, 90, Math.PI, 0); ctx.fill(); ctx.lineWidth = 7; ctx.strokeStyle = K.INK; ctx.stroke(); for (let r = 0; r < 4; r++) { ctx.strokeStyle = 'rgba(0,0,0,0.15)'; ctx.lineWidth = 4; ctx.beginPath(); ctx.arc(x, 1300, 20 + r * 18, Math.PI, 0); ctx.stroke(); } } else { K.E(ctx, x, 1250, 50, 70, c, 0, 7); for (let r = 0; r < 6; r++) K.E(ctx, x + Math.cos(r) * 40, 1180 + Math.sin(r * 2 + t) * 6, 10, 26, c, r, 3); } } }
function savanna(ctx, K, t, nightT = true) { bg(ctx, K, nightT ? '#0b1030' : '#ffd9a0', nightT ? '#2a2a5a' : '#fff1d0'); if (nightT) stars(ctx, K, t, 120); ctx.fillStyle = nightT ? '#3a3020' : '#d9b46a'; ctx.fillRect(K.X0, 1150, K.XW, 800); for (let i = 0; i < 4; i++) { const x = -600 + i * 800; K.R(ctx, x - 18, 850, 36, 300, 8, '#4a3220', 6); K.E(ctx, x, 830, 260, 70, nightT ? '#2a3a20' : '#5f8a3a', 0, 7); } }
function beetle(ctx, K, x, y, s, t, ball = 1) { ctx.save(); ctx.translate(x, y); ctx.scale(s, s); if (ball) { ctx.save(); ctx.translate(-120, -40); ctx.rotate(t * 3); K.C(ctx, 0, 0, 95, '#6b4a2b', 8); for (let i = 0; i < 6; i++) K.C(ctx, Math.cos(i) * 50, Math.sin(i * 2) * 50, 10, '#4a3220', 0); ctx.restore(); } K.E(ctx, 60, -10, 70, 45, '#1b1c25', 0, 7); ctx.strokeStyle = '#4cc9f0'; ctx.lineWidth = 4; ctx.beginPath(); ctx.moveTo(60, -55); ctx.lineTo(60, 35); ctx.stroke(); K.C(ctx, 135, -5, 28, '#1b1c25', 6); ctx.strokeStyle = K.INK; ctx.lineWidth = 8; for (let l = 0; l < 3; l++) { ctx.beginPath(); ctx.moveTo(30 + l * 30, 20); ctx.lineTo(10 + l * 40 + Math.sin(t * 12 + l) * 14, 60); ctx.stroke(); } ctx.restore(); }
function turtle(ctx, K, x, y, s, t, rot = 0) { ctx.save(); ctx.translate(x, y); ctx.rotate(rot); ctx.scale(s, s); const f = Math.sin(t * 10) * 0.5; for (const [fx, fy, d] of [[50, -40, 1], [50, 40, -1], [-50, -35, 1], [-50, 35, -1]]) { ctx.save(); ctx.translate(fx, fy); ctx.rotate(d * (0.6 + f * d)); K.E(ctx, 0, d * 25, 18, 35, '#5fae5a', 0, 5); ctx.restore(); } K.E(ctx, 0, 0, 70, 55, '#3f7a3a', 0, 7); for (let i = 0; i < 3; i++) K.E(ctx, -30 + i * 30, 0, 14, 20, '#2f6a2a', 0, 0); K.C(ctx, 85, 0, 26, '#5fae5a', 6); K.C(ctx, 95, -10, 5, K.INK, 0); ctx.restore(); }
function top(ctx, K, x, y, s, t, lean, wob = 0.2) { ctx.save(); ctx.translate(x, y); ctx.rotate(lean + Math.sin(t * 3) * wob); ctx.scale(s, s); K.P(ctx, [[0, 0], [-150, -260], [150, -260]], '#ff8a65', 8); K.E(ctx, 0, -260, 150, 40, '#ffd166', 0, 8); for (let i = 0; i < 4; i++) { ctx.strokeStyle = 'rgba(0,0,0,0.2)'; ctx.lineWidth = 6; const sx = Math.sin(t * 20 + i * 1.6) * 120; ctx.beginPath(); ctx.moveTo(sx, -255); ctx.lineTo(sx * 0.3, -60); ctx.stroke(); } K.R(ctx, -14, -380, 28, 120, 8, '#7b5cff', 6); ctx.restore(); }
function tiltEarth(ctx, K, x, y, r, t, deg) { const a2 = deg * Math.PI / 180; ctx.save(); ctx.translate(x, y); ctx.rotate(a2); ctx.setLineDash([16, 12]); ctx.lineWidth = 8; ctx.strokeStyle = '#ffffff'; ctx.beginPath(); ctx.moveTo(0, -r * 1.5); ctx.lineTo(0, r * 1.5); ctx.stroke(); ctx.setLineDash([]); ctx.restore(); earth(ctx, K, x, y, r, t, a2); }
function mirrorPanel(ctx, K, x, y, s) { ctx.save(); ctx.translate(x, y); ctx.scale(s, s); K.R(ctx, -120, -80, 240, 160, 10, '#c9ccd6', 7); for (let r = 0; r < 4; r++) for (let c = 0; c < 6; c++) K.C(ctx, -95 + c * 38, -55 + r * 37, 15, '#bfe9ff', 3); K.R(ctx, -12, 80, 24, 100, 4, '#9aa0ad', 4); ctx.restore(); }
function dayClock(ctx, K, x, y, r, hrs, t) { K.C(ctx, x, y, r, '#ffffff', 10); for (let i = 0; i < 24; i++) { const an = i / 24 * Math.PI * 2 - Math.PI / 2; K.C(ctx, x + Math.cos(an) * r * 0.85, y + Math.sin(an) * r * 0.85, i % 6 ? 4 : 9, K.INK, 0); } const frac = hrs / 24, an = frac * Math.PI * 2 - Math.PI / 2; ctx.fillStyle = 'rgba(255,209,102,0.6)'; ctx.beginPath(); ctx.moveTo(x, y); ctx.arc(x, y, r * 0.75, -Math.PI / 2, an); ctx.fill(); ctx.lineWidth = 10; ctx.strokeStyle = '#ff3b30'; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + Math.cos(an) * r * 0.8, y + Math.sin(an) * r * 0.8); ctx.stroke(); }
function bird(ctx, K, x, y, s, t, col = '#2b3a66') { ctx.save(); ctx.translate(x, y); ctx.scale(s, s); const f = Math.sin(t * 10) * 0.6; ctx.strokeStyle = col; ctx.lineWidth = 10; ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(-60, -20 * f); ctx.quadraticCurveTo(-30, -30, 0, 0); ctx.quadraticCurveTo(30, -30, 60, -20 * f); ctx.stroke(); ctx.restore(); }
const fmt = (n) => Math.round(n).toLocaleString('en-US');

