  // 36 Los corales notan el cambio de luz lunar (además de la temperatura) para sincronizarse; si no, huevos y esperma no se encuentran
  36: (ctx, a, K) => { reef(ctx, K, a.t); moon(ctx, K, 540, 330, 70, 0.8); for (let i = 0; i < 3; i++) { ctx.fillStyle = 'rgba(255,246,216,0.12)'; ctx.beginPath(); ctx.moveTo(500, 380); ctx.lineTo(580, 380); ctx.lineTo(900 + i * 300, 1300); ctx.lineTo(100 - i * 300, 1300); ctx.fill(); } const k = K.ph(a.t, a.d, 0.5, 0.9); K.C(ctx, -300, 800 - k * 100, 30, '#ff8ab8', 5); K.C(ctx, 1400, 800 - k * 100, 30, '#ffc2e0', 5); K.text(ctx, 'DIFFERENT NIGHTS', 540, 1000, { size: 70, color: '#ffffff', k }); ctx.setLineDash([16, 12]); ctx.lineWidth = 6; ctx.strokeStyle = '#ff3b30'; ctx.beginPath(); ctx.moveTo(-250, 800 - k * 100); ctx.lineTo(1350, 800 - k * 100); ctx.stroke(); ctx.setLineDash([]); cross(ctx, K, 540, 800 - k * 100, 60, k); },
  // 37 Menos corales bebé: arrecifes que ya cuestan recuperarse sufrirían más; albergan cerca de un cuarto de las especies marinas
  37: (ctx, a, K) => { reef(ctx, K, a.t); const k = K.ph(a.t, a.d, 0.1, 0.5); veil(ctx, K, '#c9c4b8', 0.35 * k); K.C(ctx, 1450, 700, 220, '#ffffff', 9); ctx.fillStyle = '#ff8a65'; ctx.beginPath(); ctx.moveTo(1450, 700); ctx.arc(1450, 700, 210, -Math.PI / 2, -Math.PI / 2 + Math.PI * 0.5 * K.ph(a.t, a.d, 0.4, 0.7)); ctx.fill(); K.text(ctx, '¼ OF MARINE SPECIES', 1450, 1000, { size: 56, color: '#ffffff', k: K.ph(a.t, a.d, 0.6, 0.8) }); for (let i = 0; i < 5; i++) K.prop(ctx, 'pez', -500 + i * 250, 650 + (i % 2) * 100, 0.3, a.t); },
  // 38 Una sabana africana de noche: un escarabajo pelotero rueda una bola de estiércol casi tan grande como él
