  // 39 Para rodar en línea recta necesita una brújula en el cielo: usa el patrón de luz polarizada alrededor de la Luna
  39: (ctx, a, K) => { savanna(ctx, K, a.t); moon(ctx, K, 540, 460, 90); for (let i = 0; i < 12; i++) { const an = i / 12 * Math.PI * 2; ctx.strokeStyle = 'rgba(191,233,255,0.6)'; ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(540 + Math.cos(an) * 140, 460 + Math.sin(an) * 140); ctx.lineTo(540 + Math.cos(an) * (300 + 40 * Math.sin(a.t * 3 + i)), 460 + Math.sin(an) * (300 + 40 * Math.sin(a.t * 3 + i))); ctx.stroke(); } beetle(ctx, K, -200 + K.ph(a.t, a.d, 0, 1) * 1000, 1250, 1.3, a.t); ctx.setLineDash([20, 14]); ctx.lineWidth = 8; ctx.strokeStyle = '#ffd166'; ctx.beginPath(); ctx.moveTo(-500, 1350); ctx.lineTo(1700, 1350); ctx.stroke(); ctx.setLineDash([]); K.text(ctx, 'SKY COMPASS', 1450, 800, { size: 70, color: '#ffd166', k: K.ph(a.t, a.d, 0.4, 0.6) }); },
  // 40 En noches sin luna usan el brillo de la Vía Láctea: listo, pero es más débil y las nubes lo arruinan
  40: (ctx, a, K) => { savanna(ctx, K, a.t); ctx.save(); ctx.globalAlpha = 0.45; ctx.fillStyle = '#c9b8ff'; ctx.beginPath(); ctx.ellipse(540, 500, 1600, 120, -0.15, 0, 7); ctx.fill(); ctx.restore(); stars(ctx, K, a.t, 200); const c = K.ph(a.t, a.d, 0.55, 0.9); for (let i = 0; i < 6; i++) K.E(ctx, -800 + i * 500 + a.t * 40, 500, 300 * c, 100 * c, 'rgba(40,40,60,0.9)', 0, 0); const wob = c * Math.sin(a.t * 3) * 0.5; ctx.save(); ctx.translate(540, 1250); ctx.rotate(wob); beetle(ctx, K, 0, 0, 1.3, a.t); ctx.restore(); K.text(ctx, '?', 540, 1000, { size: 120, color: '#ffffff', k: c }); },
  // 41 Una playa tranquila de Florida: una tortuguita sale del huevo y tiene minutos para llegar al agua
  41: (ctx, a, K) => { beach(ctx, K, a.t); for (let i = 0; i < 6; i++) K.E(ctx, 200 + (i % 3) * 90, 1500 + Math.floor(i / 3) * 60, 40, 30, '#f6f2e6', 0, 5); const k = K.ph(a.t, a.d, 0.1, 0.3); ctx.save(); ctx.translate(380, 1500); ctx.rotate(Math.sin(a.t * 12) * 0.1 * (1 - k)); K.E(ctx, 0, 0, 45, 35, '#f6f2e6', 0, 5); ctx.restore(); turtle(ctx, K, 380 + K.ph(a.t, a.d, 0.3, 1) * 500, 1500 - K.ph(a.t, a.d, 0.3, 1) * 80, 0.6, a.t, -0.3); K.text(ctx, 'FLORIDA', -500, 450, { size: 80, color: '#ffd166' }); K.text(ctx, 'MINUTES', 1300, 700, { size: 90, color: '#ff8a65', k: K.ph(a.t, a.d, 0.5, 0.7) }); },
  // 42 Las crías van hacia el horizonte más brillante: el mar abierto, donde el cielo y el agua reflejan estrellas y luna
  42: (ctx, a, K) => { beach(ctx, K, a.t); moon(ctx, K, 900, 500, 120); ctx.fillStyle = 'rgba(255,246,216,0.3)'; ctx.beginPath(); ctx.moveTo(850, 1000); ctx.lineTo(950, 1000); ctx.lineTo(1300, 1380); ctx.lineTo(500, 1380); ctx.fill(); for (let i = 0; i < 6; i++) { const q = K.clamp((a.t / a.d) * 1.2 - i * 0.05); turtle(ctx, K, -300 + i * 220 + q * (900 - (-300 + i * 220)) * 0.6, 1600 - q * 250, 0.45, a.t + i, -1.2 + (i - 3) * 0.1); } K.text(ctx, 'BRIGHTEST HORIZON', 900, 350, { size: 70, color: '#ffffff', k: K.ph(a.t, a.d, 0.3, 0.5) }); },
  // 43 Farolas y hoteles ya las engañan para que vayan al revés; sin luz lunar, el mar perdería esa batalla aún más
  43: (ctx, a, K) => { beach(ctx, K, a.t, 0.3); for (let i = 0; i < 3; i++) { K.R(ctx, -700 + i * 250, 600, 220, 800, 10, '#2a2c50', 8); for (let r = 0; r < 8; r++) for (let c = 0; c < 2; c++) { ctx.fillStyle = '#ffd76b'; ctx.fillRect(-680 + i * 250 + c * 100, 640 + r * 90, 60, 50); } } K.R(ctx, 300, 700, 20, 700, 6, '#3a3a44', 6); K.radial(ctx, 310, 700, 300, '#ffd76b', 0.7); for (let i = 0; i < 5; i++) { const q = K.clamp(a.t / a.d * 1.1 - i * 0.05); turtle(ctx, K, 1100 + i * 120 - q * 700, 1550 - q * 100 + (i % 2) * 50, 0.45, a.t + i, Math.PI + 0.2); } K.text(ctx, 'WRONG WAY', 900, 450, { size: 100, color: '#ff3b30', k: K.ph(a.t, a.d, 0.4, 0.6) }); },
  // 44 El plancton también: algunas criaturas suben y bajan con el brillo de la Luna, y los peces comen con ese horario
  44: (ctx, a, K) => { bg(ctx, K, '#0e4a7a', '#020d1f'); moon(ctx, K, 1600, 280, 60, 0.7); const lvl = 0.5 + 0.5 * Math.sin(a.t * 1.2); for (let i = 0; i < 120; i++) { const x = K.X0 + 400 + (i * 113) % 2900, y = 500 + lvl * 700 + ((i * 53) % 300) + Math.sin(a.t * 2 + i) * 10; K.C(ctx, x, y, 5, '#9affd6', 0); } for (let i = 0; i < 5; i++) K.prop(ctx, 'pez', -500 + ((a.t * 120 + i * 500) % 2600), 450 + lvl * 700, 0.35, a.t); K.R(ctx, -780, 450, 60, 900, 20, '#ffffff', 6); K.C(ctx, -750, 500 + lvl * 800, 30, '#9affd6', 5); K.text(ctx, 'UP & DOWN', 540, 1500, { size: 70, color: '#9affd6' }); },
  // 45 Búhos, murciélagos y polillas ajustan cómo cazan y se esconden según el brillo de la noche
