  // 46 Mito 3 equivocado: a los animales les importa mucho; sus relojes se romperían y la naturaleza necesitaría miles de generaciones
  46: (ctx, a, K) => { night(ctx, K, a.t); K.C(ctx, 540, 820, 260, '#ffffff', 10); ctx.save(); ctx.translate(540, 820); ctx.rotate(0.4 + Math.sin(a.t * 20) * 0.05); ctx.lineWidth = 14; ctx.strokeStyle = K.INK; ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, -200); ctx.stroke(); ctx.restore(); ctx.lineWidth = 8; ctx.strokeStyle = K.INK; ctx.beginPath(); ctx.moveTo(400, 600); ctx.lineTo(560, 820); ctx.lineTo(480, 1050); ctx.stroke(); busted(ctx, K, 540, 450, K.ph(a.t, a.d, 0.15, 0.35), 'WRONG'); K.text(ctx, '1,000s OF GENERATIONS', 540, 1250, { size: 70, color: '#ffffff', k: K.ph(a.t, a.d, 0.55, 0.75) }); },
  // 47 Mito 4: las estaciones seguirían igual, porque vienen del Sol y no de la Luna
  47: (ctx, a, K) => { bg(ctx, K, '#8fd3ff', '#e6f7ff'); const S = [['#5fc36a', 'SPRING'], ['#ffd23f', 'SUMMER'], ['#ff8a00', 'FALL'], ['#ffffff', 'WINTER']]; S.forEach(([c, l], i) => { const x = -600 + i * 720; K.C(ctx, x, 1150, 160, c, 8); K.text(ctx, l, x, 1150, { size: 50, color: '#2b3a66' }); }); myth(ctx, K, a, 4, 'SEASONS STAY THE SAME'); },
  // 48 Realidad: la Luna es una mano que estabiliza la inclinación de la Tierra; sin ella, las estaciones podrían descontrolarse
  48: (ctx, a, K) => { night(ctx, K, a.t); const k = K.ph(a.t, a.d, 0.4, 0.6); tiltEarth(ctx, K, 540, 850, 260, a.t, 23.5 + (k > 0 ? Math.sin(a.t * 2) * 25 * k : 0)); moon(ctx, K, 1400, 700, 80, 1 - k, false); if (k < 1) { ctx.save(); ctx.globalAlpha = 1 - k; K.prop(ctx, 'mano', 1050, 650, 0.5, a.t, -0.6); ctx.restore(); } reality(ctx, K, -300, 450, K.ph(a.t, a.d, 0, 0.2)); },
  // 49 La Tierra gira inclinada unos 23,5 grados: por eso hay calor en verano y nieve en diciembre
  49: (ctx, a, K) => { night(ctx, K, a.t); sun(ctx, K, 540, 850, 120); const an = a.t * 0.7; for (const [ph, lbl] of [[0, 'SUMMER'], [Math.PI, 'WINTER']]) { const x = 540 + Math.cos(an + ph) * 1000, y = 850 + Math.sin(an + ph) * 300; tiltEarth(ctx, K, x, y, 110, a.t, 23.5); K.text(ctx, lbl, x, y + 200, { size: 50, color: ph ? '#bfe9ff' : '#ffd166' }); } K.text(ctx, '23.5°', 540, 420, { size: 140, color: '#ffffff', k: K.ph(a.t, a.d, 0.1, 0.3) }); },
  // 50 Una peonza con la base algo floja: si nada la estabiliza, se inclina más y empieza a vagar
