  // 51 Hoy la gravedad de la Luna hace que la inclinación solo oscile un par de grados, en ciclos de decenas de miles de años
  51: (ctx, a, K) => { night(ctx, K, a.t); tiltEarth(ctx, K, 300, 850, 260, a.t, 23.5 + Math.sin(a.t * 1.5) * 1.2); moon(ctx, K, 900, 600, 70, 1, false); K.R(ctx, 1200, 650, 640, 400, 20, '#ffffff', 8); ctx.lineWidth = 8; ctx.strokeStyle = '#2b3a66'; ctx.beginPath(); for (let x = 0; x <= 560; x += 10) { const y = 850 + Math.sin(x / 50 + a.t) * 30; x ? ctx.lineTo(1240 + x, y) : ctx.moveTo(1240, y); } ctx.stroke(); K.text(ctx, '± ~2°', 1520, 1150, { size: 80, color: '#ffd166' }); },
  // 52 Sin Luna, el Sol y los demás planetas podrían ir empujando esa inclinación, quizá decenas de grados
  52: (ctx, a, K) => { night(ctx, K, a.t); sun(ctx, K, -600, 800, 160); const k = K.ph(a.t, a.d, 0.1, 1); tiltEarth(ctx, K, 540, 850, 240, a.t, 23.5 + Math.sin(a.t * 1.2) * 35 * k); [['#e0734a', 1300, 500, 50], ['#e9c89a', 1650, 900, 100], ['#f0d9a0', 1300, 1250, 80]].forEach(([c, x, y, r]) => { K.C(ctx, x, y, r, c, 7); ctx.strokeStyle = 'rgba(255,209,102,0.6)'; ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(x - r, y); ctx.lineTo(820, 850); ctx.stroke(); }); K.text(ctx, 'TENS OF DEGREES', 540, 1350, { size: 70, color: '#ff8a65', k: K.ph(a.t, a.d, 0.5, 0.7) }); },
  // 53 Tranquilo, es lento: millones de años. Pero lento no significa inofensivo. Avancemos
  53: (ctx, a, K) => { bg(ctx, K, '#1b1f4a', '#3a2a6a'); const n = Math.floor(K.ph(a.t, a.d, 0.1, 0.8) * 5_000_000); K.text(ctx, fmt(n) + ' YRS', 540, 650, { size: 130, color: '#ffd166' }); K.prop(ctx, 'reloj_arena', 540, 1050, 0.8, a.t, Math.sin(a.t * 6) * 0.05); for (let i = 0; i < 5; i++) K.text(ctx, '»', 1100 + i * 120 + ((a.t * 200) % 120), 1050, { size: 120, color: '#ffffff' }); K.text(ctx, 'NOT HARMLESS', -300, 1050, { size: 70, color: '#ff8a65', k: K.ph(a.t, a.d, 0.5, 0.7) }); },
  // 54 Digamos que la Tierra se inclina más de 60 grados: en verano tu hemisferio apunta casi directo al Sol y no se pone en meses
  54: (ctx, a, K) => { bg(ctx, K, '#ffe1b8', '#ffb347'); sun(ctx, K, 1400 + Math.cos(a.t) * 120, 500 + Math.sin(a.t) * 40, 150); floor(ctx, K, 1250, '#d9b46a'); for (let i = 0; i < 6; i++) { ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(-600 + i * 400, 1200); ctx.quadraticCurveTo(-580 + i * 400, 1150 + Math.sin(a.t * 6 + i) * 20, -600 + i * 400, 1100); ctx.stroke(); } tiltEarth(ctx, K, -300, 700, 200, a.t, 62); stand(ctx, a, K, 540, 1450, 0.16, you(a), 'worried'); K.text(ctx, '60°+', -300, 1050, { size: 90, color: '#ff3b30' }); K.text(ctx, 'NO SUNSET FOR MONTHS', 1100, 1100, { size: 60, color: '#7a2333', k: K.ph(a.t, a.d, 0.4, 0.6) }); },
  // 55 Luego llega el invierno: meses de oscuridad y un frío feroz que lo congela todo
  55: (ctx, a, K) => { bg(ctx, K, '#0b1030', '#2a3a6a'); stars(ctx, K, a.t, 120); floor(ctx, K, 1250, '#e6eef4'); for (let i = 0; i < 80; i++) K.C(ctx, K.X0 + (i * 211) % K.XW + Math.sin(a.t + i) * 20, 250 + ((a.t * 200 + i * 97) % 1100), 6, '#ffffff', 0); for (let i = 0; i < 4; i++) { const x = -600 + i * 650; K.prop(ctx, 'arbol', x, 1250, 0.8, a.t); K.E(ctx, x, 1000, 160, 40, '#ffffff', 0, 5); } K.R(ctx, 1300, 500, 90, 600, 40, '#ffffff', 8); ctx.fillStyle = '#4cc9f0'; ctx.fillRect(1320, 1080 - 100, 50, 100); K.C(ctx, 1345, 1120, 70, '#4cc9f0', 8); K.text(ctx, 'MONTHS OF DARK', 540, 450, { size: 90, color: '#bfe9ff', k: K.ph(a.t, a.d, 0.2, 0.4) }); },
  // 56 Bosques, granjas y ciudades se hicieron para estaciones suaves: cambios así inutilizarían casi toda la tierra de cultivo
  56: (ctx, a, K) => { const sw = Math.sin(a.t * 3); bg(ctx, K, sw > 0 ? '#ffe1b8' : '#c9d6e3', sw > 0 ? '#ffb347' : '#e6eef4'); floor(ctx, K, 1150, sw > 0 ? '#c9a45a' : '#ffffff'); for (let r = 0; r < 3; r++) for (let i = 0; i < 16; i++) { const x = -700 + i * 170 + r * 40, y = 1250 + r * 90; ctx.strokeStyle = sw > 0 ? '#a8862a' : '#bfe9ff'; ctx.lineWidth = 8; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + (sw > 0 ? 30 : 0), y - 60 + (sw > 0 ? 30 : 0)); ctx.stroke(); } K.R(ctx, 1300, 800, 400, 350, 10, '#c0392b', 9); K.P(ctx, [[1270, 800], [1500, 620], [1730, 800]], '#8a2a20', 9); K.text(ctx, sw > 0 ? 'SCORCHED' : 'FROZEN', 540, 500, { size: 120, color: sw > 0 ? '#ff3b30' : '#4cc9f0' }); cross(ctx, K, 0, 800, 150, K.ph(a.t, a.d, 0.6, 0.85)); K.text(ctx, 'FARMLAND', 0, 1050, { size: 60, color: '#2b3a66' }); },
  // 57 Los científicos aún discuten cuánto; otras fuerzas ayudan, pero coinciden en que la Luna mantiene la calma
